const input = $input.item.json;

const prompts = {
  new_items: `Create 3 new menu items for Mitch street food that:
- Combine Romanian ingredients with ${input.cuisine_style || 'modern fusion'}
- Target ${input.target_audience || 'young professionals in Bucharest'}
- Price range: ${input.price_range || '20-40 RON'}
- Current season: ${input.season || 'current'}
For each item provide: Name, Description, Key Ingredients, Suggested Price, Marketing Hook`,

  refine_item: `Improve this menu item: ${input.item_name}
Current description: ${input.current_description}
Feedback to address: ${input.feedback}
Provide: Improved name, Enhanced description, Ingredient tweaks, New marketing angle`,

  seasonal: `Create a seasonal menu (${input.season}) with 5 items using:
- Seasonal Romanian ingredients available in ${input.season}
- Transylvanian theme
- Instagram-worthy presentation ideas
- Cost-effective ingredients`,

  competitor_analysis: `Analyze this competitor item: ${input.competitor_item}
From: ${input.competitor_name}
How can Mitch create something better that:
- Uses authentic Romanian ingredients
- Has stronger Transylvanian branding
- Offers better value
- Is more Instagrammable`
};

const selectedPrompt = prompts[input.workflow_type || 'new_items'];

return [{
  json: {
    prompt: selectedPrompt,
    workflow_type: input.workflow_type,
    context: input
  }
}];

const aiResponse = $input.item.json;
const context = $node['Build Menu Prompt'].json.context;

return [{
  json: {
    workflow_type: context.workflow_type,
    request_timestamp: new Date().toISOString(),
    ai_suggestions: aiResponse.results[0].response,
    model_used: aiResponse.results[0].model,
    input_parameters: context,
    mitch_branding_tip: "Remember: Emphasize Transylvanian heritage and vampire theme for social media appeal!"
  }
}];
